class Solution {
    public int[] stockSpan(int[] arr, int n) {
        Stack <int[]>s=new Stack<>();
        int ans[]=new int[n];
        for(int i=0;i<n;i++){
            int cnt=1;
            int el=arr[i];
            while(!s.isEmpty() && s.peek()[0]<=el){
                cnt+=s.peek()[1];
                s.pop();
            }
            s.push(new int[]{el,cnt});
            ans[i]=cnt;
        }
        return ans;
    }

}

```

